package com.crowdin.client.core.http.impl.json;

import com.crowdin.client.core.http.exceptions.CrowdinApiException;
import com.crowdin.client.projectsgroups.model.Project;
import org.junit.Test;
import org.junit.Rule;
import org.junit.rules.ExpectedException;

import java.text.ParseException;

import static org.junit.Assert.*;

public class JacksonJsonTransformerTest {

    @Test
    public void parseValidJsonTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();

        String validJson = "{\"id\": 1, \"name\": \"Project Test\"}";

        Project project = transformer.parse(validJson, Project.class);

        assertNotNull(project);
        assertEquals(new Integer(1), project.getId());
        assertEquals("Project Test", project.getName());
    }

    @Test
    public void parseInvalidJsonTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        expectedEx.expect(CrowdinApiException.class);
        expectedEx.expectMessage("Error while parsing JSON");

        String invalidJson = "{\"id\": \"abc\", \"name\": 123}";
        transformer.parse(invalidJson, Project.class);
    }

    @Test
    public void parseJsonWithExtraDataTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();

        String jsonWithExtraData = "{\"id\": 1, \"name\": \"Project Test\", \"extraData\": \"Other Data\"}";

        Project project = transformer.parse(jsonWithExtraData, Project.class);

        assertNotNull(project);
        assertEquals(new Integer(1), project.getId());
        assertEquals("Project Test", project.getName());
    }

    @Test
    public void convertValidObjectTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        Project project = new Project();
        project.setId(1);
        project.setName("Project Test");

        String result = transformer.convert(project);

        assertEquals("{\"id\":1,\"name\":\"Project Test\"}", result);
    }

    public void convertNullObjectTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        expectedEx.expect(IllegalArgumentException.class);
        expectedEx.expectMessage("Object is null");

        transformer.convert(null);
    }
}
